DROP TABLE IF EXISTS [REGIONES];
DROP TABLE IF EXISTS [PAIS];
DROP TABLE IF EXISTS [EQUIPOS];

CREATE TABLE [REGIONES] (
[LCK] INTEGER(255) DEFAULT 1,
[LPL] INTEGER(255) DEFAULT 2,
[LEC] INTEGER(255) DEFAULT 3,
[LCS] INTEGER(255) DEFAULT 4,
[LPC] INTEGER(255) DEFAULT 5);

CREATE TABLE [PAIS] (
[KR] INTEGER(255) DEFAULT 1,
[CN] INTEGER(255) DEFAULT 2,
[EU] INTEGER(255) DEFAULT 3,
[NA] INTEGER(255) DEFAULT 4,
[APAC] INTEGER(255) DEFAULT 5,

FOREIGN KEY([KR]) REFERENCES [REGIONES]([LCK]) ON DELETE SET NULL ON UPDATE SET NULL,
FOREIGN KEY([CN]) REFERENCES [REGIONES]([LPL]) ON DELETE SET NULL ON UPDATE SET NULL,
FOREIGN KEY([EU]) REFERENCES [REGIONES]([LEC]) ON DELETE SET NULL ON UPDATE SET NULL,
FOREIGN KEY([NA]) REFERENCES [REGIONES]([LCS]) ON DELETE SET NULL ON UPDATE SET NULL,
FOREIGN KEY([APAC]) REFERENCES [REGIONES]([LPC]) ON DELETE SET NULL ON UPDATE SET NULL);

